import * as THREE from 'three';
import {OrbitControls} from 'three/addons/controls/OrbitControls.js';
import {batchData,fitTrain,fitValidation,predict} from './ai-training-model.js';
export function mountTrainingScene(host,read,advance){const renderer=new THREE.WebGLRenderer({alpha:true,antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));host.append(renderer.domElement);renderer.domElement.setAttribute('role','img');renderer.domElement.setAttribute('aria-label','กลไก Batch และกราฟ Training เทียบ Validation สามมิติ');const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(42,1,.1,100),controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.enablePan=false;controls.minDistance=8;controls.maxDistance=26;scene.add(new THREE.HemisphereLight(0xe6ffff,0x172d3c,3));const grid=new THREE.GridHelper(16,20,0x35576b,0x224153);grid.position.y=-2.5;scene.add(grid);let group,labels=[],motions=[],elapsed=0,last=performance.now(),key='',raf,disposed=false;const V=(x,y,z=0)=>new THREE.Vector3(x,y,z);const resetView=()=>{camera.position.set(0,4,16);controls.target.set(0,0,0);controls.update();};resetView();
 const label=(text,p)=>{const el=document.createElement('div');el.className='node-label';el.textContent=text;if(text.startsWith('Train\n')||text.startsWith('Validation\n')){p.x=Math.sign(p.x)*4.2;p.y=1.2;}host.append(el);labels.push({el,p});};
 const point=(p,color,size=.08)=>{const m=new THREE.Mesh(new THREE.SphereGeometry(size,12,8),new THREE.MeshStandardMaterial({color}));m.position.copy(p);group.add(m);return m;};
 const line=(pts,color)=>group.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),new THREE.LineBasicMaterial({color})));
 function clear(){labels.forEach(l=>l.el.remove());labels=[];motions=[];if(group){group.traverse(o=>{o.geometry?.dispose();o.material?.dispose();});scene.remove(group);}group=new THREE.Group();scene.add(group);}
 function rebuild(s){clear();elapsed=0;if(s.topic==='batch'){const r=s.record,selected=new Set(r?.data.map(p=>p.id)||[]);batchData.forEach((p,i)=>{const a=V(-4+(i%4)*.65,1.2-Math.floor(i/4)*.7);const m=point(a,selected.has(p.id)?0xffd079:0x53798e,.15);label(String(p.id),a.clone().add(V(0,.35)));if(selected.has(p.id)&&s.step>=1)motions.push({m,a,b:V(0,.5)});});point(V(0,.5),0x73dfc3,.35);point(V(3,.5),0x9fbcee,.35);line([V(0,.5),V(3,.5)],0x75cdbb);label(`Dataset · 8ตัวอย่าง\nเหลือง=Batchล่าสุด`,V(-3,2.5));label(r?`Gradientเฉลี่ย\ndw ${r.g.dw.toFixed(3)}\ndb ${r.g.db.toFixed(3)}`:'รอคำนวณBatch',V(0,2.5));const p=s.step===2?s.batch:r?.before||s.batch;label(`w ${p.w.toFixed(3)}\nb ${p.b.toFixed(3)}`,V(3,1.6));label(`Epoch ${s.batch.epoch} · Updates ${s.batch.updates}\nการเล่นภาพไม่เพิ่มUpdates`,V(0,-1.8));if(r&&s.step===2){const m=point(V(0,.5),0xffd079);motions.push({m,a:V(0,.5),b:V(3,.5)});}}
 else {const f=s.fit;for(const [data,z,color,name]of [[fitTrain,1.6,0x7bdec4,'Train'],[fitValidation,-1.6,0xc89aef,'Validation']]){const place=(x,y)=>V(x*3,y*1.6,z);line(Array.from({length:101},(_,i)=>{const x=-1+i*.02;return place(x,predict(f.coeff,x));}),0xffd079);line([place(-1,0),place(1,0)],0x54778a);data.forEach(p=>{const a=place(p.x,p.y),b=place(p.x,predict(f.coeff,p.x));point(a,color);if(s.step>=1)line([a,b],color);const m=point(a,0xffd079,.045);motions.push({m,a,b});});label(`${name}\nMSE ${(name==='Train'?f.trainLoss:f.validationLoss).toFixed(5)}`,V(name==='Train'?-3.8:3.8,2.1,z));}label(`Degree ${f.degree} · พารามิเตอร์ ${f.coeff.length}\nเส้นเดียวกัน ไม่fitจากValidation`,V(0,3.2));label('เขียว Train · ม่วง Validation\nทอง Prediction · เส้นตั้ง Error',V(0,-2.3));}
 }
 function frame(now){if(disposed)return;const s=read(),k=s.revision+':'+s.step;if(key!==k){key=k;rebuild(s);}const dt=Math.min(50,now-last);last=now;if(s.playing)elapsed+=dt*s.speed;const t=Math.min(1,elapsed/1600),smooth=t*t*(3-2*t);motions.forEach(({m,a,b})=>m.position.lerpVectors(a,b,smooth));renderer.domElement.dataset.playhead=elapsed.toFixed(1);controls.update();labels.forEach(({el,p})=>{const n=p.clone().project(camera);el.style.left=`${(n.x*.5+.5)*host.clientWidth}px`;el.style.top=`${(-n.y*.5+.5)*host.clientHeight}px`;el.hidden=n.z< -1||n.z>1;});renderer.render(scene,camera);if(s.playing&&elapsed>=2300){elapsed=2300;advance();}raf=requestAnimationFrame(frame);}
 const resize=()=>{renderer.setSize(host.clientWidth,host.clientHeight);camera.aspect=host.clientWidth/host.clientHeight;camera.updateProjectionMatrix();};const ro=new ResizeObserver(resize);ro.observe(host);resize();raf=requestAnimationFrame(frame);return {resetView,dispose(){disposed=true;cancelAnimationFrame(raf);ro.disconnect();controls.dispose();clear();renderer.dispose();renderer.domElement.remove();}};
}
